import sys


def main():
    values = map(int, sys.stdin.buffer.read().split())
    n = next(values)
    x = next(values)

    frequencies = [1]
    for value in values:
        if value < x:
            frequencies.append(1)
        else:
            frequencies[-1] += 1

    total_squares = sum(count * count for count in frequencies)
    answers = ["0"] * (n + 1)
    answers[0] = str((total_squares - n - 1) // 2)

    maximum = len(frequencies) - 1
    if maximum:
        width = (total_squares.bit_length() + 7) // 8

        forward = int.from_bytes(
            b"".join(count.to_bytes(width, "little") for count in frequencies),
            "little",
        )
        backward = int.from_bytes(
            b"".join(
                count.to_bytes(width, "little")
                for count in reversed(frequencies)
            ),
            "little",
        )

        coefficients = (forward * backward).to_bytes(
            (2 * maximum + 1) * width, "little"
        )

        offset = (maximum + 1) * width
        for k in range(1, maximum + 1):
            answers[k] = str(
                int.from_bytes(coefficients[offset:offset + width], "little")
            )
            offset += width

    sys.stdout.write(" ".join(answers))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
